window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9c02be0317863d51"]={"versions": [{"id": "FIG-9c02be0317863d51", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm (AUTOSAR Layered Software Architecture) aus der Perspektive des CAN State Managers (CanSM). Das Diagramm verortet den CanSM sowie angrenzende Software-Module innerhalb der AUTOSAR-Basessoftware (BSW), gegliedert in die Domänen bzw. Layer <strong>System Services</strong>, <strong>Communication Services</strong> und <strong>Communication Hardware Abstraction</strong> sowie die angrenzenden Hardware-Treiberbereiche. Grau hinterlegte Komponenten heben CAN-spezifische Module und Protokollinstanzen hervor, während hellblau/violett gefärbte Blöcke generische oder übergeordnete BSW-Module darstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Komponentenblöcke und Domänen:</p>\n<ul class=\"fig-list\">\n<li><strong>System Services</strong>:</li>\n<li><code>EcuM</code> (ECU State Manager): Vertikal gestreckter Funktionsblock zur Steuerung des Steuergeräte-Lebenszyklus.</li>\n<li><code>Dem</code> (Diagnostic Event Manager): Block für Diagnoseereignisse und Fehlerspeicherung.</li>\n<li><code>ComM</code> (Communication Manager): Koordiniert Kommunikationsanforderungen der Anwendungs- und Systemschicht.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Communication Services</strong>:</li>\n<li><code>CAN State Manager</code> (CanSM, grau): Zentraler Zustandsmanager für das CAN-Netzwerk, erstreckt sich vertikal über die Kommunikationsdienst-Ebene bis an die Abstraktionsschicht.</li>\n<li><code>AUTOSAR COM</code>: Schnittstelle zur Signalübertragung für Applikationen.</li>\n<li><code>DCM Diagnostic Com. Manager</code>: Diagnose-Kommunikationsmanager.</li>\n<li><code>Generic NM Interface / NM GW</code>: Netzwerkmanagement-Interface und Gateway.</li>\n<li><code>CAN NM</code> (grau): CAN-spezifisches Netzwerkmanagement direkt unterhalb des generischen NM-Interfaces.</li>\n<li><code>PDU Router</code> (PDU-Routing) und <code>IPDU multiplexer</code> (Multiplexing von Signal-PDUs).</li>\n<li><code>CAN Transport Protocol</code> (CanTp, grau): CAN-Transportschicht für segmentierte Datenübertragung unterhalb des PDU-Routers.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Communication Hardware Abstraction</strong>:</li>\n<li><code>CAN Interface</code> (CanIf, grau): Horizontale Schicht, die die oberen Kommunikationsdienste an die CAN-Treiber anbindet.</li>\n<li><code>CAN Transceiver Driver</code> (grau): Ansteuerung des physischen CAN-Transceivers.</li>\n<li><code>Driver for ext. CAN ASIC</code> (grau): Treiber für externe CAN-Controller/ASICs.</li>\n<li>Ein unbeschrifteter Funktionsblock (rechts unter CanIf) für interne CAN-Treiberkomponenten (MCAL CAN Driver).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Schichtenmodell ohne explizite Ablauf- oder Sequenzpfade. Die Anordnung verdeutlicht strukturelle Kontroll- und Datenflüsse:</p>\n<ul class=\"fig-list\">\n<li>Der <code>CAN State Manager</code> interagiert auf Systemebene mit <code>ComM</code>, <code>EcuM</code> und <code>Dem</code> zur Zustandsverwaltung, Initialisierung und Fehlerbehandlung des CAN-Subsystems.</li>\n<li>Nach unten steuert der <code>CAN State Manager</code> direkt das <code>CAN Interface</code> (CanIf), um CAN-Controller und Transceiver in die entsprechenden Modi (z. B. Start, Stop, Sleep) zu versetzen.</li>\n<li>Kommunikationsdatenpfade verlaufen vertikal von <code>AUTOSAR COM</code>, <code>DCM</code> und <code>CAN NM</code> über <code>PDU Router</code> bzw. <code>CAN Transport Protocol</code> in das <code>CAN Interface</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm legt die funktionale Einbettung des CAN State Managers in die AUTOSAR-Architektur normativ fest. Für Entwickler und Integratoren definiert die Darstellung:</p>\n<ul class=\"fig-list\">\n<li>CanSM ist als BSW-Komponente innerhalb der Communication Services angesiedelt und fungiert als Bindeglied zwischen den Systemdiensten (insb. ComM) und der Hardware-Abstraktion (CanIf).</li>\n<li>CanSM übernimmt keine direkte Datenweiterleitung (PDU-Verarbeitung), sondern ist rein auf das Zustands- und Kontrollmanagement des CAN-Stacks fokussiert.</li>\n<li>Abhängigkeiten bestehen auf Steuerungsebene zu EcuM, Dem, ComM sowie CanIf.</li>\n</ul>"}, {"id": "FIG-659606edf9f680a2", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm (AUTOSAR Layered Software Architecture) aus der Perspektive des CAN State Managers (CanSM). Das Diagramm verortet den CanSM sowie angrenzende Software-Module innerhalb der AUTOSAR-Basessoftware (BSW), gegliedert in die Domänen bzw. Layer <strong>System Services</strong>, <strong>Communication Services</strong> und <strong>Communication Hardware Abstraction</strong> sowie die angrenzenden Hardware-Treiberbereiche. Grau hinterlegte Komponenten heben CAN-spezifische Module und Protokollinstanzen hervor, während hellblau/violett gefärbte Blöcke generische oder übergeordnete BSW-Module darstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Komponentenblöcke und Domänen:</p>\n<ul class=\"fig-list\">\n<li><strong>System Services</strong>:</li>\n<li><code>EcuM</code> (ECU State Manager): Funktionsblock zur Steuerung der Zustände des Gesamtsystems.</li>\n<li><code>BswM</code> (Basic Software Mode Manager): Unterhalb von <code>EcuM</code> angeordneter Block zur koordinierenden Modusverwaltung der Basessoftware.</li>\n<li><code>Dem</code> (Diagnostic Event Manager): Block für Diagnoseereignisse und Fehlerspeicherung.</li>\n<li><code>ComM</code> (Communication Manager): Koordiniert Kommunikationsanforderungen der Anwendungs- und Systemschicht.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Communication Services</strong>:</li>\n<li><code>CAN State Manager</code> (CanSM, grau): Zentraler Zustandsmanager für das CAN-Netzwerk, erstreckt sich vertikal über die Kommunikationsdienst-Ebene bis an die Abstraktionsschicht.</li>\n<li><code>AUTOSAR COM</code>: Schnittstelle zur Signalübertragung für Applikationen.</li>\n<li><code>DCM Diagnostic Com. Manager</code>: Diagnose-Kommunikationsmanager.</li>\n<li><code>Generic NM Interface / NM GW</code>: Netzwerkmanagement-Interface und Gateway.</li>\n<li><code>CAN NM</code> (grau): CAN-spezifisches Netzwerkmanagement direkt unterhalb des generischen NM-Interfaces.</li>\n<li><code>PDU Router</code> (PDU-Routing) und <code>IPDU multiplexer</code> (Multiplexing von Signal-PDUs).</li>\n<li><code>CAN Transport Protocol</code> (CanTp, grau): CAN-Transportschicht für segmentierte Datenübertragung unterhalb des PDU-Routers.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Communication Hardware Abstraction</strong>:</li>\n<li><code>CAN Interface</code> (CanIf, grau): Horizontale Schicht, die die oberen Kommunikationsdienste an die CAN-Treiber anbindet.</li>\n<li><code>CAN Transceiver Driver</code> (grau): Ansteuerung des physischen CAN-Transceivers.</li>\n<li><code>Driver for ext. CAN ASIC</code> (grau): Treiber für externe CAN-Controller/ASICs.</li>\n<li>Ein unbeschrifteter Funktionsblock (rechts unter CanIf) für interne CAN-Treiberkomponenten (MCAL CAN Driver).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Schichtenmodell ohne explizite Ablauf- oder Sequenzpfade. Die Anordnung verdeutlicht strukturelle Kontroll- und Datenflüsse:</p>\n<ul class=\"fig-list\">\n<li>Der <code>CAN State Manager</code> interagiert auf Systemebene mit <code>ComM</code>, <code>EcuM</code>, <code>BswM</code> und <code>Dem</code> zur Zustandsverwaltung, Moduskoordination, Initialisierung und Fehlerbehandlung des CAN-Subsystems.</li>\n<li>Nach unten steuert der <code>CAN State Manager</code> direkt das <code>CAN Interface</code> (CanIf), um CAN-Controller und Transceiver in die entsprechenden Modi (z. B. Start, Stop, Sleep) zu versetzen.</li>\n<li>Kommunikationsdatenpfade verlaufen vertikal von <code>AUTOSAR COM</code>, <code>DCM</code> und <code>CAN NM</code> über <code>PDU Router</code> bzw. <code>CAN Transport Protocol</code> in das <code>CAN Interface</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm legt die funktionale Einbettung des CAN State Managers in die AUTOSAR-Architektur normativ fest. Für Entwickler und Integratoren definiert die Darstellung:</p>\n<ul class=\"fig-list\">\n<li>CanSM ist als BSW-Komponente innerhalb der Communication Services angesiedelt und fungiert als Bindeglied zwischen den Systemdiensten (insb. ComM, BswM) und der Hardware-Abstraktion (CanIf).</li>\n<li>CanSM übernimmt keine direkte Datenweiterleitung (PDU-Verarbeitung), sondern ist rein auf das Zustands- und Kontrollmanagement des CAN-Stacks fokussiert.</li>\n<li>Abhängigkeiten bestehen auf Steuerungsebene zu EcuM, BswM, Dem, ComM sowie CanIf.</li>\n</ul>"}], "trans": [{"from": "FIG-9c02be0317863d51", "to": "FIG-659606edf9f680a2", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Unter <strong>System Services</strong> wurden die drei vertikalen Blöcke <code>EcuM</code>, <code>Dem</code> und <code>ComM</code> verkürzt und ein neuer Block <code>BswM</code> (Basic Software Mode Manager) unterhalb von <code>EcuM</code> eingefügt.</li>\n</ul>"}]};
